import sys
sys.setrecursionlimit(2000)

def carmichael(n):
    # returns Carmichael function λ(n)
    if n == 1:
        return 1
    # factorize n
    # quick and dirty factorization for n up to 100000
    factors = {}
    temp = n
    p = 2
    while p * p <= temp:
        while temp % p == 0:
            factors[p] = factors.get(p, 0) + 1
            temp //= p
        p += 1 if p == 2 else 2  # skip even after 2
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    # compute λ for each prime power and lcm
    lambdas = []
    for p, e in factors.items():
        if p == 2:
            if e == 1:
                lamb = 1
            elif e == 2:
                lamb = 2
            else:
                lamb = 2**(e-2)
        else:
            lamb = p**e - p**(e-1)
        lambdas.append(lamb)
    # compute lcm
    def lcm(a, b):
        return a * b // math.gcd(a, b)
    import math
    result = 1
    for lamb in lambdas:
        result = lcm(result, lamb)
    return result

def tower_mod(h, m):
    if h == 1:
        return 9 % m
    lam = carmichael(m)
    exp = tower_mod(h-1, lam)
    return pow(9, exp, m)

# Test with small heights
for h in range(1, 6):
    print(f"h={h}, mod 100 = {tower_mod(h, 100)}")
# Let's compute for h=1001 mod 100000
result = tower_mod(1001, 100000)
print(f"Result for h=1001 mod 100000: {result}")
print(f"Last five digits: {result:05d}")

def phi(n):
    result = n
    p = 2
    temp = n
    while p * p <= temp:
        if temp % p == 0:
            while temp % p == 0:
                temp //= p
            result -= result // p
        p += 1 if p == 2 else 2
    if temp > 1:
        result -= result // temp
    return result

def tower_mod_phi(h, m):
    if h == 1:
        return 9 % m
    phi_m = phi(m)
    exp = tower_mod_phi(h-1, phi_m)
    return pow(9, exp, m)

